def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos2(value, default=(0, 0)):
        try:
            x, y = value[0], value[1]
            return int(x), int(y)
        except Exception:
            return default

    def step_toward(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_by_distance(items, src, prefer_far=False):
        best_item = None
        best_score = None
        for item in items:
            try:
                p = pos2(item)
                score = manhattan(src, p)
                if prefer_far:
                    score = -score
                if best_score is None or score < best_score:
                    best_score = score
                    best_item = p
            except Exception:
                pass
        return best_item

    env = observation.get("environment_name", "resource_collection")
    self_pos = pos2(observation.get("self_position", (0, 0)))
    opp_pos = pos2(observation.get("opponent_position", self_pos))

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        gw = observation.get("grid_width", 0)
        gh = observation.get("grid_height", 0)
        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        if corners:
            target = max(corners, key=lambda c: manhattan(c, opp_pos))
            return step_toward(self_pos, target)
        return step_toward(opp_pos, self_pos)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        target = best_by_distance(targets, self_pos, prefer_far=False)
        if target is not None:
            return step_toward(self_pos, target)
        gw = observation.get("grid_width", 0)
        gh = observation.get("grid_height", 0)
        if gw and gh:
            center = (gw // 2, gh // 2)
            return step_toward(self_pos, center)
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_cells") or []
    if resources:
        target = best_by_distance(resources, self_pos, prefer_far=False)
        if target is not None:
            move = step_toward(self_pos, target)
            if opp_pos != self_pos:
                next_pos = (self_pos[0] + move[0], self_pos[1] + move[1])
                if manhattan(next_pos, opp_pos) <= 1:
                    away = step_toward(opp_pos, self_pos)
                    if away != [0, 0]:
                        return away
            return move

    return step_toward(self_pos, opp_pos)

